<template><section v-loading="loading"><el-row :gutter="16"><el-col :xs="24" :lg="14"><el-card shadow="never"><template #header><div class="header"><b>审批工作流</b><el-button type="primary" @click="workflowDialog=true">新建规则</el-button></div></template><el-table :data="workflows"><el-table-column prop="name" label="名称" /><el-table-column prop="project_id" label="项目范围" /><el-table-column prop="min_amount" label="最低金额" /><el-table-column prop="max_amount" label="最高金额" /><el-table-column prop="priority" label="优先级" width="90" /><el-table-column label="步骤" width="80"><template #default="{row}">{{row.steps?.length||0}}</template></el-table-column></el-table></el-card></el-col><el-col :xs="24" :lg="10"><el-card shadow="never"><template #header><b>角色授权</b></template><el-form label-width="90px"><el-form-item label="用户 ID"><el-input-number v-model="roleForm.user_id" :min="1" /></el-form-item><el-form-item label="财务角色"><el-select v-model="roleForm.role"><el-option v-for="role in roles" :key="role" :label="role" :value="role" /></el-select></el-form-item><el-form-item label="项目范围"><el-select v-model="roleForm.project_id" clearable><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="grant">授权</el-button></el-form-item></el-form></el-card><el-card shadow="never" class="import-card"><template #header><b>历史数据迁移</b></template><p>导入是显式后台任务；GET 请求不会扫描 Obsidian 或写入数据库。</p><el-button @click="importLegacy(true)">迁移预检</el-button><el-button type="warning" @click="importLegacy(false)">执行 SQLite 导入</el-button></el-card></el-col></el-row><el-dialog v-model="workflowDialog" title="新建审批工作流" width="650px"><el-form label-width="100px"><el-form-item label="名称"><el-input v-model="workflowForm.name" /></el-form-item><el-form-item label="项目"><el-select v-model="workflowForm.project_id" clearable><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id" /></el-select></el-form-item><el-form-item label="金额区间"><el-input-number v-model="workflowForm.min_amount" :min="0" /> 至 <el-input-number v-model="workflowForm.max_amount" :min="0" /></el-form-item><el-form-item label="审批步骤"><div class="steps"><div v-for="(step,index) in workflowForm.steps" :key="index"><el-input v-model="step.name" placeholder="步骤名称" /><el-select v-model="step.assignee_role"><el-option label="reviewer" value="reviewer" /><el-option label="project_manager" value="project_manager" /><el-option label="finance_admin" value="finance_admin" /></el-select><el-button type="danger" text @click="workflowForm.steps.splice(index,1)">删除</el-button></div><el-button @click="workflowForm.steps.push({name:'财务复核',assignee_role:'reviewer'})">增加步骤</el-button></div></el-form-item></el-form><template #footer><el-button @click="workflowDialog=false">取消</el-button><el-button type="primary" @click="createWorkflow">保存</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{financeApi,type FinanceProject}from'@/api/finance';const loading=ref(false),workflowDialog=ref(false),workflows=ref<Record<string,any>[]>([]),projects=ref<FinanceProject[]>([]);const roles=['finance_admin','project_manager','applicant','reviewer','cashier','auditor'];const roleForm=reactive({user_id:1,role:'applicant',project_id:''});const workflowForm=reactive<{name:string;project_id:string;min_amount:number;max_amount:number;priority:number;steps:Array<{name:string;assignee_role:string}>}>({name:'',project_id:'',min_amount:0,max_amount:0,priority:100,steps:[{name:'财务复核',assignee_role:'reviewer'}]});async function load(){loading.value=true;try{[workflows.value,projects.value]=await Promise.all([financeApi.workflows(),financeApi.projects()])}finally{loading.value=false}}async function grant(){await financeApi.grantRole({...roleForm,project_id:roleForm.project_id||null});ElMessage.success('财务角色已授权')}async function createWorkflow(){await financeApi.createWorkflow({...workflowForm,project_id:workflowForm.project_id||null,max_amount:workflowForm.max_amount||null});workflowDialog.value=false;ElMessage.success('审批工作流已创建');await load()}async function importLegacy(dry_run:boolean){if(!dry_run)await ElMessageBox.confirm('将从只读历史 SQLite 导入到当前权威库，确认继续？','执行迁移',{type:'warning'});const result=await financeApi.createImport({source_type:'legacy_sqlite',dry_run});ElMessage.success(dry_run?`预检完成：${JSON.stringify(result.result_payload||{})}`:'迁移任务已完成')}onMounted(load)</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}.import-card{margin-top:16px}.import-card p{color:var(--el-text-color-secondary);line-height:1.6}.steps{width:100%}.steps>div{display:grid;grid-template-columns:1fr 180px 60px;gap:8px;margin-bottom:8px}</style>
